using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 public static class DialoguePersistenceChecksV06 {
  sealed class Store:IStateStore{public PlayerState Data=new PlayerState();public bool Fail;public int Writes;public PlayerState Load(out string notice){notice="";return Data.Clone();}public bool Save(PlayerState s,out string error){Writes++;error=Fail?"test disk failure":"";if(Fail)return false;Data=s.Clone();return true;}}
  static int checks;static void Check(bool ok,string text){checks++;if(!ok)throw new Exception(text);}
  static void Action(DialoguePresenter d,string name){typeof(DialoguePresenter).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(d,null);}
  static void Tick(DialoguePresenter d){typeof(DialoguePresenter).GetField("nextCheck",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(d,0f);d.Tick();}
  public static string Run(){checks=0;int changed=0;var ui=new VisualElement();var room=new VisualElement();ui.Add(room);var store=new Store{Fail=true};var session=new GameSession(store,new SeededRandom(1));var d=new DialoguePresenter(session,ui,room,()=>false,()=>changed++);Tick(d);Action(d,"Advance");Check(store.Writes==1&&changed==1&&session.Model.Snapshot.tutorial.step==0,"failed Next reports change without advancing");for(int i=0;i<100;i++)Tick(d);Check(store.Writes==1,"no automatic tutorial write retry");store.Fail=false;Action(d,"Advance");Check(session.Model.Snapshot.tutorial.step==1,"Next retries explicitly");store.Fail=true;Action(d,"Skip");Check(!session.Model.Snapshot.tutorial.skipped&&changed==3,"failed Skip remains visible and reports error");store.Fail=false;Action(d,"Skip");Check(session.Model.Snapshot.tutorial.skipped,"Skip retry durable");int writes=store.Writes;d.Replay();for(int i=0;i<5;i++)Action(d,"Advance");Check(store.Writes==writes&&session.Model.Snapshot.cash==0&&session.Model.Snapshot.spins==0,"help replay has no writes or resource grants");d.Dispose();
   var state=new PlayerState{cash=123,spins=9};state.purchased[0]=state.purchased[1]=true;state.tutorial.completed=true;store=new Store{Data=new GameModel(state).Snapshot};session=new GameSession(store,new SeededRandom(2));bool modal=true;d=new DialoguePresenter(session,ui,room,()=>modal,()=>changed++);Tick(d);Check(store.Writes==0&&session.Model.Snapshot.tutorial.storySeenMask==0,"modal cannot consume queued story");modal=false;Tick(d);Check(room.Q<VisualElement>("heroine-dialogue").style.display==DisplayStyle.Flex&&store.Writes==0,"story displayed without marking seen or writing");d.Dispose();session=new GameSession(store,new SeededRandom(2));d=new DialoguePresenter(session,ui,room,()=>false,()=>changed++);Tick(d);Check(room.Q<VisualElement>("heroine-dialogue").style.display==DisplayStyle.Flex,"undismissed story returns on reload");store.Fail=true;Action(d,"Advance");Check(store.Writes==1&&session.Model.Snapshot.tutorial.storySeenMask==0,"failed story acknowledgment preserves pending story");for(int i=0;i<100;i++)Tick(d);Check(store.Writes==1,"100 story ticks do not retry failed disk write");store.Fail=false;Action(d,"Advance");Check(store.Writes==2&&session.Model.Snapshot.tutorial.storySeenMask==1,"successful explicit dismissal commits once");Check(TutorialPolicy.PendingStory(new GameSession(store,new SeededRandom(2)).Model.Snapshot)==-1,"acknowledged story stays dismissed");Check(session.Model.Snapshot.cash==123&&session.Model.Snapshot.spins==9&&session.Model.PurchasedCount==2,"dialogue preserves resources and ownership");d.Dispose();string result="PASS "+checks+" dialogue persistence checks; counted store failure/retry/modal/relaunch/help/resource invariants; synthetic calls, no OS input";File.WriteAllText(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Evidence","dialogue-persistence-v06-checks.txt"),result);return result;}
 }
}
